import snapshot from './npb2026.json'
import type { Dataset } from './data'
import eligibilitySnapshot from './eligibility2026.json'
import type { EligibilityFacts } from './eligibility'

// Generated by scripts/update_npb_data.py from the 36 URLs recorded in sources.
// Roster membership/statistics are official facts; draft eligibility is separate.
export const officialDataset: Dataset = {
  ...(snapshot as Dataset),
  players: (snapshot as Dataset).players.map((p) => ({
    ...p,
    draftFacts: (
      eligibilitySnapshot.players as Record<string, EligibilityFacts>
    )[p.id] ?? {
      salaryYear: 2026,
      salaryManYen: null,
      salarySource: null,
      checkedAt: eligibilitySnapshot.asOf,
      exclusions: [],
      holds: ['候補条件データが未収録'],
      unresolved: ['条件データ更新待ち'],
    },
  })),
}
